  "Adds bodycams to the register and updates the ones already there, matched by serial number. Who has a bodycam right now never changes by import; that happens only when it is booked out or handed back.": "E eketsa dikhamera tsa mmele rejistareng mme e ntjhafatsa tse seng di le teng, ka ho bapisa nomoro ya serial. Ya tshwereng khamera ya mmele hona jwale ha a fetohe ka ho kenya; seo se etsahala feela ha e ntshwa kapa e kgutliswa.",
  "Adds firearms to the register and updates the ones already there, matched by serial number. Who holds a firearm right now never changes by import; that happens only when it is booked out or handed back.": "E eketsa dithunya rejistareng mme e ntjhafatsa tse seng di le teng, ka ho bapisa nomoro ya serial. Ya tshwereng sethunya hona jwale ha a fetohe ka ho kenya; seo se etsahala feela ha se ntshwa kapa se kgutliswa.",
  "Adds people to the staff register and updates the ones already there, matched by badge number. Nobody gets access: each person is invited afterwards and activates their own account.": "E eketsa batho rejistareng ya basebetsi mme e ntjhafatsa ba seng ba le teng, ka ho bapisa nomoro ya beche. Ha ho motho ya fumanang phihlello: motho e mong le e mong o a memuwa kamora moo mme a bule akhaonte ya hae.",
  "Adds vehicles to the register and updates the ones already there, matched by department and unit number. A vehicle’s status never changes by import: one off the road stays off the road until fleet control returns it.": "E eketsa dikoloi rejistareng mme e ntjhafatsa tse seng di le teng, ka ho bapisa lefapha le nomoro ya yuniti. Boemo ba koloi ha bo fetohe ka ho kenya: e seng tseleng e dula e se tseleng ho fihlela taolo ya dikoloi e e kgutlisa.",
  "Adjustment": "Phetoho",
  "Admin": "Motsamaisi",
  "Admin-configurable operational lists. Everything is a soft delete — history is never lost.": "Manane a tshebetso a hlophiswang ke motsamaisi. Tsohle di hlakolwa ka bonolo — nalane ha e lahlehe le ka mohla.",
