  "EC": "EC",
  "EMERGENCY MEDICAL SERVICES": "DITSHEBELETSO TSA TSHOHANYETSO TSA BONGAKA",
  "EMERGENCY MEDICAL SERVICES · DOCTOR": "DITSHEBELETSO TSA TSHOHANYETSO TSA BONGAKA · NGAKA",
  "EMERGENCY MEDICAL SERVICES · START OF SHIFT": "DITSHEBELETSO TSA TSHOHANYETSO TSA BONGAKA · QALO YA SHIFI",
