  "ETCO2": "ETCO2",
  "EVIDENCE ({n})": "BOPAKI ({n})",
  "Each call sign is a row: pick the member for it.": "Letshwao le leng le le leng la ho bitsa ke moraro: kgetha setho sa lona.",
  "Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.": "Letshwao le leng le le leng la ho bitsa ke sebaka se le seng sa mosebetsi: moo le patrolang teng, dihora tsa lona, phomolo ya lona le maemo ao le a hlokang. Kabo ya Mosebetsi e bea basebetsi ho tsona.",
  "Each call sign with its area, hours and the rank it needs.": "Letshwao le leng le le leng la ho bitsa le sebaka sa lona, dihora le maemo ao le a hlokang.",
  "Each day's reports, by where they stand.": "Ditlaleho tsa letsatsi le leng le le leng, ho ya ka moo di emeng teng.",
  "Each link or code works once and expires after {invitationTtlHours} hours. Sending again cancels the old one.": "Sehokelo kapa khoutu e nngwe le e nngwe e sebetsa hang mme e fela kamora dihora tse {invitationTtlHours}. Ho romela hape ho hlakola ya kgale.",
  "Each member’s record as the old system kept it: numbers, rank, station, section, weekend group, contacts, LEO record and screen access.": "Rekoto ya setho se seng le se seng jwaloka tsamaiso ya kgale e e bolokileng: dinomoro, maemo, seteišene, karolo, sehlopha sa mafelo-beke, bohokahanyi, rekoto ya LEO le phihlello ya sekrine.",
  "Each patient and how bad they are": "Mokudi e mong le e mong le hore o maemong a mabe hakae",
  "Each person gets their own invitation, as their confirmed role, by the route shown: email where HR gave an address, SMS where there is only a cellphone{value}, otherwise a printed code. Each link or code works once and expires after its set time.": "Motho e mong le e mong o fumana memo ya hae, jwalo ka mosebetsi wa hae o netefaditsweng, ka tsela e bontshitsweng: imeile moo HR e faneng ka aterese, SMS moo ho nang le selefounu feela{value}, ho seng jwalo khoutu e hatisitsweng. Sehokelo kapa khoutu e nngwe le e nngwe e sebetsa hang mme e fela kamora nako ya yona e behilweng.",
  "Each rule acts at most once per thing per threshold — a call that breaches its SLA raises one alert at each tier, not one every five minutes. Thresholds are stored per rule, so changing “escalate after 10 minutes” to 15 needs no deployment. Every change and every manual run is written to the audit trail with your name on it.": "Molao o mong le o mong o etsa hang feela nthong e nngwe le e nngwe moeding o mong le o mong — mohala o fetang SLA ya ona o tsosa temoso e le nngwe boemong bo bong le bo bong, eseng e le nngwe metsotso e meng le e meng e mehlano. Meedi e bolokwa ka molao o mong le o mong, kahoo ho fetola \"eketsa kamora metsotso e 10\" ho ya ho 15 ha ho hloke ho kenngwa. Phetoho e nngwe le e nngwe le ho etsa ho hong le ho hong ka letsoho ho ngolwa motlhaleng wa tlhahlobo le lebitso la hao.",
  "Each service's identity — crest, colours and naming — as it appears across the platform, the responder app and printed reports.": "Boitsebiso ba tshebeletso e nngwe le e nngwe — letshwao, mebala le mabitso — jwalo ka ha bo hlaha sethaleng sohle, ho app ya baarabi le ditlalehong tse hatisitsweng.",
