  "Email address (their sign-in)": "Aterese ya imeile (eo ba kenang ka yona)",
  "Email is not set up on this server, so pass these on yourself. Production always emails them.": "Imeile ha e a hlophiswa sebeletsing sena, kahoo di fetisetse ka bowena. Tshebediso ya nnete e di romela ka imeile ka mehla.",
  "Email or badge number": "Imeile kapa nomoro ya beche",
