  "Emergency Medical Services · Administration": "Ditshebeletso tsa Tshohanyetso tsa Bongaka · Tsamaiso",
  "Emergency contact": "Motho wa kgokahano nakong ya tshohanyetso",
  "Emergency equipment stocked & accessible": "Disebediswa tsa tshohanyetso di tletse mme di a fihlelleha",
  "Emergency lights & siren functioning": "Mabone a tshohanyetso le serene di a sebetsa",
  "Emergency — hold to call for assistance": "Tshohanyetso — tshwara ho kopa thuso",
  "Emergency-flagged rows are highlighted. Resolve inline once handled.": "Mela e tshwailweng e le tshohanyetso e a totobatswa. E rarolle mona hang ha e se e sebetsitswe.",
  "Emotional Wellbeing (Feeling mentally balanced?)": "Boiketlo ba maikutlo (Na o ikutlwa o lekalekane kelellong?)",
  "Employee": "Mosebetsi",
  "Employee name": "Lebitso la mosebetsi",
  "Employment status": "Boemo ba mosebetsi",
  "Emulators and simulators cannot register for push. Alerts still arrive while the app is open.": "Di-emulator le di-simulator di ke ke tsa ingodisetsa ditsebiso. Ditemoso di ntse di fihla ha app e butswe.",
  "En Route": "O tseleng",
  "En route": "O tseleng",
  "Enabled": "Ho butswe",
  "Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.": "Ho bula sebopeho ha ho fe mosebetsi letho leo matrix ya ditsela le polokeho ya boemo ba mola di neng di ke ke tsa le dumella — ditsamaiso tse pedi di sebetsa mmoho. Ho tima se seng ho se pata hohle mme ho etsa hore ditsela tsa sona tsa sebeletsi di hane, mohiring ona feela.",
  "End": "Qetello",
  "End of shift": "Qetello ya shifi",
