  "End standby": "Qeta ho emela",
  "End standby?": "Qeta ho emela?",
  "End time": "Nako ya qetello",
  "End your shift": "Qeta shifi ya hao",
  "End your shift and go off duty.": "Qeta shifi ya hao mme o tswe mosebetsing.",
  "Ending a shift in the app is not switched on for this server yet. Hand your kit in at the counter and tell your supervisor.": "Ho qeta shifi ka app ha ho eso bulwe sebeletsing sena. Fana ka disebediswa tsa hao khaontareng mme o bolelle molaodi wa hao.",
  "Endorsement added": "Endorsement e eketsitswe",
