  "Everything is filled in.": "Tsohle di tladitswe.",
  "Everything on the register for one ID number or one vehicle: fines, payments and when they were made, and what is owed today.": "Tsohle tse rejistareng tsa nomoro e le nngwe ya boitsebiso kapa koloi e le nngwe: dikotlo, ditefello le hore di entswe neng, le se kolotwang kajeno.",
  "Everything that came in while you were busy, with what still needs your acknowledgement.": "Tsohle tse fihlileng ha o ne o tshwarehile, le tse ntseng di hloka kamohelo ya hao.",
  "Everything they recorded stays: incidents, reports and their history.": "Tsohle tseo ba di ngotseng di a dula: diketsahalo, ditlaleho le nalane ya tsona.",
