  "For a call that will never have a report: a hoax, a duplicate, or the caller cancelled.{value}": "Mohala o ke keng wa ba le tlaleho: leshano, o pheteditsweng, kapa moletsi o hlakotse.{value}",
  "For a notice issued in error. It stays on the register, marked cancelled, with your reason. Refund any money first.": "Tsebiso e ntshitsweng ka phoso. E dula rejistareng, e tshwailwe e le e hlakotsweng, le lebaka la hao. Kgutlisa tjhelete efe kapa efe pele.",
  "For a notice written in a notice book. Copy it exactly as written, with the printed notice number. Notices at the roadside are issued on the phone, where the infringer signs.": "Tsebiso e ngotsweng bukeng ya ditsebiso. E kopitse hantle jwalo ka ha e ngotswe, le nomoro ya tsebiso e hatisitsweng. Ditsebiso tsa tseleng di ntshuwa mohaleng, moo motlodi a saenang teng.",
  "For example towards the taxi rank": "Mohlala, ho lebisa sebakeng sa ditekesi",
  "For example: radio from a security guard": "Mohlala: seea-le-moya se tswang ho molebedi wa tshireletso",
  "For example: the caller rang back with the right address": "Mohlala: moletsi o leditse hape ka aterese e nepahetseng",
  "For leave on a form the member handed in, sick leave, or an absence such as AWOL. It is approved as captured and their duty in those dates is marked.": "Bakeng sa phomolo foromong eo setho se e kentseng, phomolo ya bokudi, kapa ho se be teng jwaloka AWOL. E amohelwa jwaloka e kentswe mme mosebetsi wa bona matsatsing ao o tshwauwa.",
  "For the whole organisation. Office-hours rotations skip them, and they are not counted as leave days.": "Ya mokgatlo wohle. Ho fapanyetsana ha dihora tsa ofisi ho a di tlola, mme ha di balwe jwalo ka matsatsi a phomolo.",
  "For their shift": "Ya shifti ya bona",
  "For you, your role, your department and everyone.": "Ya hao, ya mosebetsi wa hao, ya lefapha la hao le ya bohle.",
