  "How HikTech is designed to work, agreed between eThekwini and the build team. Visible to administrators only.": "Kamoo HikTech e etseditsweng ho sebetsa kateng, ho dumellanwe pakeng tsa eThekwini le sehlopha sa ho aha. E bonwa ke batsamaisi feela.",
