  "How often this rule is evaluated. The scheduler ticks every 5 minutes, so anything below that runs every tick.": "Hore molao ona o hlahlojwa hangata hakae. Sehlophisi se sebetsa metsotso e meng le e meng e 5, ka hona eng kapa eng e ka tlase ho moo e sebetsa nako le nako.",
