  "I am at the scene": "Ke sebakeng",
  "I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.": "Ha ke nke sethunya shifing ena (mohl. sa ka ha se rejisetareng ya polokelo ya dibetsa). Sena se ngolwa rekotong ya ka ya qalo ya shifi.",
  "I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.": "Ha ke apare bodycam shifing ena. Lebaka la ka le rekotong ya ka ya qalo ya shifi mme mookamedi wa ka o a le bona.",
  "I checked this ambulance and its stock myself, and the answers above are accurate.": "Ke hlahlobile ambulense ena le disebediswa tsa yona ka bonna, mme dikarabo tse ka hodimo di nepahetse.",
  "I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.": "Ke netefatsa hore ke hlahlobile koloi e ka hodimo ka mmele le hore tlhahisoleseding e ngotsweng e nepahetse ho ya ka tsebo ya ka. Diphoso dife kapa dife tse bonweng di tlameha ho tlalehelwa mookamedi hanghang le ho ngolwa bukeng ya semmuso ya pokotho.",
  "I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.": "Ke hlalositse letsatsi la lekgotla, le hore ho lefa kamohelo ya molato ke kahlolo mme ho ka fana ka rekoto ya botlokotsebe.",
  "I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).": "Ke hlalositse tsebiso le dikgetho: lefa ka hara matsatsi a 32 bakeng sa theolelo, kopa ho lefa ka dikarolo (AARTO 04), kapa etsa boipiletso (AARTO 08).",
  "I have an activation code": "Ke na le khoutu ya ho kenya tshebetsong",
  "I have read the POPIA notice (version {POPIA_NOTICE_VERSION})": "Ke badile tsebiso ya POPIA (mofuta {POPIA_NOTICE_VERSION})",
  "I have read this shift": "Ke badile shifi ena",
  "I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.": "Ke tseba hore lefapha la hao le sebetsa jwang mme nka bala boto e phelang eo karolo ya hao e e bonang. Mpotse eng kapa eng, kapa o mpolelle seo nka se etsang. Ke a se lokisa, mme ha ho letho le fetohang ho fihlela o netefatsa.",
  "I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.": "Ke tseba shifi ya hao, mehala ya hao, phomolo ya hao le disebediswa tsa hao. Mpotse eng kapa eng ka mosebetsi wa hao, ka mantswe a hao. Ke a hlalosa mme ke o bontshe moo o lokelang ho ya teng; wena o etsa mosebetsi.",
  "I personally completed these checks and confirm that the answers and any defects recorded are accurate.": "Ke phethile ditlhahlobo tsena ka bonna mme ke netefatsa hore dikarabo le diphoso tse ngotsweng di nepahetse.",
  "I will use HikTech only for official duties and keep my password private": "Ke tla sebedisa HikTech bakeng sa mesebetsi ya semmuso feela mme ke boloke phasewete ya ka e le lekunutu",
