  "It is alleged that…": "Ho qosuwa hore…",
  "It is held on this phone and sends automatically, ahead of everything else, the moment you have signal. Do not wait — SMS or call the control room now.": "E bolokilwe founong ena mme e romelwa ka boyona, pele ho tsohle, hang ha o fumana letshwao. O se ke wa ema — romela SMS kapa o letsetse control room jwale.",
