  "Official After-Action Reports. Filing one resolves the incident.": "Ditlaleho tsa Semmuso tsa ka mora Ketso. Ho romela e le nngwe ho rarolla ketsahalo.",
  "Official insignia belong to the municipality and its services, so the platform ships none — upload each department's real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department's colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.": "Matshwao a semmuso ke a masepala le ditshebeletso tsa wona, ka hona sethala ha se a tlise — kenya letshwao la nnete la lefapha le leng le le leng mona mme le hlaha hohle hanghang. Ho fihlela ka nako eo beche ya ditlhaku tsa pele e bontshwa ka mebala ya lefapha leo, ka hona ha ho letho le shebahalang le sa qetwa. PNG kapa SVG e nang le bokamorao bo bonaletsang e sebetsa hantle; ditshwantsho tsa sekwere di balehang hantle ha di le nyane.",
