  "Only Staff Maintenance and the member can see this.": "Ke Tlhokomelo ya Basebetsi le setho feela ba ka bonang sena.",
  "Only a translator for this language approves. You can save drafts.": "Ke mofetoledi wa puo ena feela ya dumellang. O ka boloka meralo.",
  "Only approved translations are shown on the screens. Everything else shows in English.": "Diphetolelo tse dumeletsweng feela di bontshwa dikirining. Tse ding kaofela di bontshwa ka Senyesemane.",
  "Only fines I issued": "Dikotlo tseo ke di fileng feela",
  "Only if there is no emergency. Why?": "Feela ha ho se na tshohanyetso. Hobaneng?",
  "Only me": "Nna feela",
  "Only officers who went on duty in the app after today's start of shift are listed. Distance is straight-line from their last GPS heartbeat; ETA assumes {speedKmh} km/h with a {roadFactor}× road factor (Admin → Operations Settings).": "Ho thathamiswa feela bahlankedi ba keneng mosebetsing ka app ka mora qalo ya shifi ya kajeno. Sebaka ke mola o otlolohileng ho tloha letshwaong la bona la ho qetela la GPS; ETA e nka {speedKmh} km/h le ntlha ya tsela ya {roadFactor}× (Admin → Disetting tsa Tshebetso).",
  "Only one patient": "Mokudi a le mong feela",
  "Only someone senior to the member, in their department, can approve. Nobody approves their own.": "Ke motho ya hodimo ho setho feela, lefapheng la sona, ya ka dumellang. Ha ho ya itumellang.",
  "Only the firefighter leading this incident files its fire report.": "Ke setimamollo se etelletseng ketsahalo ena pele feela se romelang tlaleho ya yona ya mollo.",
