  "Road traffic offences carry the AARTO Schedule 3 charge code and penalty; by-law offences carry the by-law section and the admission of guilt amount. Enter both from the official schedules, then verify. Changing a verified code or amount takes the verification off until someone checks it again.": "Melato ya tsela e tshwere khoutu ya molato ya AARTO Schedule 3 le kotlo; melato ya molao wa masepala e tshwere karolo ya molao le tjhelete ya ho dumela molato. Kenya ka bobedi ho tswa manane a semmuso, ebe o netefatsa. Ho fetola khoutu kapa tjhelete e netefaditsweng ho tlosa netefatso ho fihlela motho a e hlahloba hape.",
  "Road traffic offences on AARTO 01 notices; by-law offences on Section 56 (offender present) or Section 341 (unattended vehicle) notices. Every charge has its own FN- number, and a served notice can never be edited or deleted — only cancelled, with a reason.": "Melato ya tsela ditsebisong tsa AARTO 01; melato ya molao wa masepala ditsebisong tsa Karolo 56 (motlodi wa molao o teng) kapa Karolo 341 (koloi e sa hlokomelweng). Molato o mong le o mong o na le nomoro ya wona ya FN-, mme tsebiso e fanweng e ke ke ya fetolwa kapa ya hlakolwa — e ka hlakolwa feela, ka lebaka.",
