  "Upholstery": "Dikwahelo tsa ditulo",
  "Upload": "Kenya",
  "Upload evidence": "Kenya bopaki",
  "Upload the day’s receipts from the cashier or the bank. Each row is matched to a fine by its FN- number or its notice number, and recorded with the date on the receipt — so a payment made inside the 32 days keeps the AARTO discount even when it is captured later. A receipt already on a fine is skipped, so importing the same file twice records nothing twice.": "Kenya diresiti tsa letsatsi ho tswa ho mmolokadi wa tjhelete kapa bankeng. Mola o mong le o mong o tshwantshwa le kotlo ka nomoro ya yona ya FN- kapa nomoro ya tsebiso ya yona, mme o ngolwa le letsatsi le resiting — ka hona tefo e entsweng ka hare ho matsatsi a 32 e boloka theolelo ya AARTO leha e kentswe hamorao. Resiti e seng e le kotlong e a tlolwa, ka hona ho kenya faele e tshwanang habedi ha ho ngole letho habedi.",
