  "You": "Wena",
  "You are backup": "O thuso",
  "You are backup on this incident — the lead {person} files the {report}.": "O thuso ketsahalong ena — moetapele {person} o romela {report}.",
  "You are backup · lead: not yet responding": "O thuso · moetapele: ha a eso arabe",
  "You are backup · lead: {name}": "O thuso · moetapele: {name}",
  "You are fit and ready to go now?": "Na o phetse hantle mme o lokiseditse ho tsamaya hona jwale?",
  "You are leading": "O etella pele",
  "You are leading this incident": "O etella pele ketsahalo ena",
  "You are not at the scene yet. The assessment is done on site; the draft is kept.": "Ha o eso fihle sebakeng. Tlhahlobo e etswa sebakeng; moralo o bolokilwe.",
  "You are not on standby": "Ha o eme",
  "You are off duty": "Ha o mosebetsing",
  "You are off duty — incidents are not sent to you. Tap to go on duty.": "Ha o mosebetsing — diketsahalo ha di romelwe ho wena. Tobetsa ho kena mosebetsing.",
  "You are off duty.": "Ha o mosebetsing.",
  "You are off duty. Go on duty to respond to incidents.": "Ha o mosebetsing. Kena mosebetsing ho araba diketsahalo.",
  "You are on duty, but today’s start of shift could not be confirmed. Check your signal and try again.": "O mosebetsing, empa qalo ya shifi ya kajeno ha e a kgona ho netefatswa. Hlahloba letshwao la hao mme o leke hape.",
  "You are on the air. Let go to listen.": "O moyeng. Tlohela ho mamela.",
  "You are on {incident_number}": "O ho {incident_number}",
  "You are still on {incident_number}. File its {report} before you end your shift.": "O sa ntse o le ho {incident_number}. Romela {report} ya yona pele o qeta shifi ya hao.",
  "You cannot change your own account. Ask another administrator.": "O ke ke wa fetola akhaonte ya hao. Kopa motsamaisi e mong.",
  "You cannot deactivate your own account.": "O ke ke wa tima akhaonte ya hao.",
  "You cannot go on standby. Speak to your supervisor, then retake the check.": "O ke ke wa ema. Bua le mookamedi wa hao, ebe o pheta tlhahlobo.",
  "You go off duty and stop receiving dispatches.": "O tswa mosebetsing mme o tlohela ho amohela tse romelwang.",
  "You go on duty once your checks are complete.": "O kena mosebetsing ha ditlhahlobo tsa hao di phethilwe.",
  "You have arrived": "O fihlile",
  "You have no duty office screens yet. Ask the systems controller for access.": "Ha o eso be le dikirini tsa ofisi ya mosebetsi. Kopa motsamaisi wa ditsamaiso phihlello.",
  "You have not applied for leave yet.": "Ha o eso etse kopo ya phomolo.",
  "You have not been placed on duty. Your answers were saved for supervisor review. Speak to your supervisor, then retake the check when your situation changes.": "Ha o a beha mosebetsing. Dikarabo tsa hao di bolokeletswe tlhahlobo ya mookamedi. Bua le mookamedi wa hao, ebe o pheta tlhahlobo ha boemo ba hao bo fetoha.",
  "You have not chosen a PIN yet. Sign in with your password once, then choose one.": "Ha o eso kgethe PIN. Kena ka phasewete ya hao hanngwe, ebe o kgetha e nngwe.",
  "You led": "Ke wena ya etelletseng pele",
  "You made this request, so a second SystemAdmin decides it. You can withdraw it.": "Ke wena ya entseng kopo ena, ka hona SystemAdmin wa bobedi o etsa qeto ka yona. O ka e hula.",
  "You may not open this camera.": "Ha o dumellwe ho bula khamera ena.",
  "You sign in with": "O kena ka",
  "You use call signs when you give out duties.": "O sebedisa matshwao a pitso ha o aba mesebetsi.",
  "You were backup": "O ne o le thuso",
  "You will be called out when you are needed.": "O tla bitswa ha o hlokahala.",
  "You will join as backup.": "O tla kena jwalo ka thuso.",
  "You will lead this incident.": "O tla etella ketsahalo ena pele.",
  "You will not be cleared until this is restocked": "O ke ke wa dumellwa ho fihlela sena se tlatswa hape",
  "You will print a slip with a one-time code and hand it to {first} in person. They sign in with{value}.": "O tla hatisa slip e nang le khoutu ya hanngwe mme o e fe {first} ka letsoho. Ba kena ka{value}.",
  "You, {ago}": "Wena, {ago}",
  "Your PIN is locked after 5 wrong tries. Enter your password to choose a new one.": "PIN ya hao e notletswe ka mora boiteko bo 5 bo fosahetseng. Kenya phasewete ya hao ho kgetha e ntjha.",
  "Your PIN is locked after 5 wrong tries. Sign in with your password and choose a new PIN, or ask your supervisor to unlock it.": "PIN ya hao e notletswe ka mora boiteko bo 5 bo fosahetseng. Kena ka phasewete ya hao mme o kgethe PIN e ntjha, kapa o kope mookamedi wa hao hore a e notlolle.",
  "Your PIN is set": "PIN ya hao e behilwe",
  "Your SOS — dispatch is sending help to you": "SOS ya hao — baromedi ba romela thuso ho wena",
  "Your SOS — help is being sent": "SOS ya hao — thuso e a romelwa",
  "Your account is ready": "Akhaonte ya hao e lokile",
  "Your arrival is not confirmed yet. It confirms itself when your phone shows you at the scene, or ask dispatch to confirm it. Then file the report.": "Ho fihla ha hao ha ho eso netefatswe. Ho tla itiisa ha founu ya hao e o bontsha o le sebakeng, kapa o kope baromedi hore ba ho netefatse. Ebe o romela tlaleho.",
  "Your badge number": "Nomoro ya hao ya beche",
  "Your balances": "Dipalanse tsa hao",
  "Your camera and microphone are live.": "Khamera le maekrofounu ya hao di a sebetsa ka nako ya nnete.",
  "Your checks are complete.": "Ditlhahlobo tsa hao di phethilwe.",
  "Your department was stood down.": "Lefapha la hao le emisitswe.",
  "Your duty status will be cleared.": "Boemo ba hao ba mosebetsi bo tla hlakolwa.",
  "Your email address or badge number": "Aterese ya hao ya imeile kapa nomoro ya beche",
