  "Your fire report is on record.": "Tlaleho ya hao ya mollo e rekotong.",
  "Your hard hat": "Katiba ya hao ya tshireletso",
  "Your incidents, live. Respond and advance status as things happen.": "Diketsahalo tsa hao, ka nako ya nnete. Araba mme o tswele pele ka boemo ha dintho di etsahala.",
  "Your kit could not be checked. You can still try to end the shift.": "Disebediswa tsa hao ha di a kgona ho hlahlojwa. O sa ntse o ka leka ho qeta shifi.",
  "Your last check ({ref}) found stock short: {items}. Restock, tick what is now on board and file again.": "Tlhahlobo ya hao ya ho qetela ({ref}) e fumane hore thepa e a haella: {items}. Tlatsa hape, tshwaya se koloing hona jwale mme o romele hape.",
  "Your location could not be found. Type the address.": "Sebaka sa hao ha se a fumanwa. Ngola aterese.",
  "Your next shift": "Shifi ya hao e latelang",
  "Your operational throughput vs the team, plus your annual appraisal ({cycleLabel}).": "Mosebetsi wa hao wa tshebetso ho bapiswa le sehlopha, hammoho le tlhahlobo ya hao ya selemo ({cycleLabel}).",
  "Your password": "Phasewete ya hao",
  "Your patient report is on record.": "Tlaleho ya hao ya mokudi e rekotong.",
