  "Your readiness declaration is on record. You are not cleared to go on duty. Contact your shift supervisor before continuing.": "Phatlalatso ya hao ya ho itokisa e rekotong. Ha o dumellwe ho kena mosebetsing. Ikopanye le mookamedi wa shifi ya hao pele o tswela pele.",
  "Your readiness declaration is on record. You are not cleared to go on duty. Contact your station officer or supervisor before continuing.": "Phatlalatso ya hao ya ho itokisa e rekotong. Ha o dumellwe ho kena mosebetsing. Ikopanye le mohlankedi wa seteishene sa hao kapa mookamedi pele o tswela pele.",
  "Your recent checks": "Ditlhahlobo tsa hao tsa morao tjena",
  "Your report for {incident_number} is on record.": "Tlaleho ya hao ya {incident_number} e rekotong.",
