  "has the procedure for each subsystem, in the order to work through them. It opens with the thing worth remembering: every procedure in it is slower than the radio. If crews are waiting, put the control room on radio and paper first, then fix the platform.": "e na le tsamaiso ya tsamaiso e nyane e nngwe le e nngwe, ka tatelano ya ho e sebetsa. E qala ka ntho e tshwanetseng ho hopolwa: tsamaiso e nngwe le e nngwe ho yona e dieha ho feta radio. Ha dihlopha di emetse, beha kamore ya taolo ho radio le pampiri pele, ebe o lokisa sethala.",
