  "is a powerful role, so a second SystemAdmin must approve this. Nothing changes until they do, and you can withdraw it meanwhile.": "ke karolo e matla, ka hona SystemAdmin wa bobedi o tshwanetse ho dumella sena. Ha ho letho le fetohang ho fihlela ba dumella, mme o ka se hula nakwana.",
